#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.
#
# shellcheck disable=SC1087,SC2317
#   SC1087: the library's "$e[Enter keeps current]" suffix is literal text after a
#     variable expansion, not an array subscript — a false positive, and the
#     library is shared verbatim across wizards so it is not rewritten here.
#   SC2317: the library carries helpers (set_secret/set_var, for gh) that this
#     particular wizard never calls; they are reachable for other wizards.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

# Cleanup for this wizard's temp files + the backgrounded `tailscale up`.
# (Library tmpfiles inside write_env are created and removed within the
# function; these live across stages, so they get the trap.)
LOG=""; FOUT=""; TS_PID=""; RENDER_OUT=""; RENDER_ERR=""; _cb_tmp=""
wizard_cleanup() {
  rm -f "$LOG" "$FOUT" "$RENDER_OUT" "$RENDER_ERR" "$_cb_tmp" 2>/dev/null || true
  # Zombie-aware liveness, not bare kill -0: an exited-but-unreaped
  # `tailscale up` (the stage-3 failure path exits with TS_PID still set)
  # would otherwise read as alive and kill an unrelated recycled PID.
  if [[ -n "$TS_PID" ]] && _alive "$TS_PID"; then
    kill "$TS_PID" 2>/dev/null || true
  fi
}

# _alive PID: zombie-aware liveness for backgrounded jobs. kill -0
# succeeds on zombies (exited but unreaped), so a bare kill -0 reads an
# instantly-dead `tailscale up` as alive and burns the wait loops. ps
# reports Z for zombies; if ps itself is missing, fall back to kill -0
# semantics rather than misreading a live process as dead.
_alive() {
  kill -0 "$1" 2>/dev/null || return 1
  local st
  # procps spells it stat=, BSD/macOS state= — try both so the helper
  # isn't silently zombie-blind off Linux.
  st=$(ps -o stat= -p "$1" 2>/dev/null || ps -o state= -p "$1" 2>/dev/null || true)
  [[ -z "$st" ]] && return 0
  [[ "$st" != *Z* ]]
}

# Installed after _alive exists, so the trap can never run it undefined.
trap wizard_cleanup EXIT INT TERM

# _check_kept_host: after taking the already-serving failure path, the
# kept funnel's hostname is unverified (the fast path above is
# hostname-bound; this one matches on error text alone). Re-read the
# status and warn on a split — same warn-don't-stop as contradictory
# presets, since a rename mid-run is legitimate.
_check_kept_host() {
  local _kh
  # Shape-filtered and boundary-anchored: `funnel status` can also carry
  # hint text with URLs (docs links, admin console), and without a boundary
  # `https://foo.ts.net.evil.com` would extract as `foo.ts.net`. Every host
  # compared here is a tailnet DNS name (<host>.<tailnet>.ts.net).
  _kh=$(tailscale funnel status 2>/dev/null | grep -oE 'https://[a-z0-9-]+(\.[a-z0-9-]+)*\.ts\.net([^a-z0-9.-]|$)' 2>/dev/null | head -n1 2>/dev/null || true)
  # Glob, not regex: strip exactly one trailing non-alnum boundary char.
  _kh="${_kh%[^a-z0-9]}"
  _kh="${_kh#https://}"
  if [[ -n "$_kh" && "$_kh" != "$TS_DNS" ]]; then
    warn "kept funnel serves ($_kh) but this run targets ($TS_DNS):"
    warn "verify with: tailscale funnel status"
  fi
}

# _valid_tsdns HOST: strict tailnet-hostname check for preset paths —
# every dot-separated label must satisfy the TS_HOST shape (lowercase,
# label-bound), and at least two labels must precede .ts.net (real
# tailnet DNS is always <host>.<tailnet> — a truncated paste like
# a.ts.net must fail here, not at the probe).
_valid_tsdns() {
  local rest="$1" label
  # RFC bounds first: label ≤63, hostname ≤253 — a 100-char-label typo
  # fails at the preset note, not at the probe.
  (( ${#rest} <= 253 )) || return 1
  [[ "$rest" == *.ts.net ]] || return 1
  rest="${rest%.ts.net}"
  # A doubled suffix (foo.ts.net.ts.net) would otherwise strip once and
  # pass label checks — reject any residual that is or ends in .ts.net
  # (note: "*.ts.net" alone also matches bare "ts.net" via empty *, so
  # both arms are needed).
  if [[ "$rest" == ts.net || "$rest" == *".ts.net" ]]; then return 1; fi
  [[ "$rest" == *.* ]] || return 1
  while [[ "$rest" == *.* ]]; do
    label="${rest%%.*}"
    (( ${#label} <= 63 )) || return 1
    [[ "$label" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?$ ]] || return 1
    rest="${rest#*.}"
  done
  (( ${#rest} <= 63 )) || return 1
  [[ "$rest" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?$ ]]
}

# _uri_host URI: the hostname part of a redirect URL, scheme- and
# port-agnostic (the preset is https-validated, but keep-recorded can
# replace it with anything). Prints the host only when it is a valid
# tailnet DNS name; callers fall back to TS_DNS otherwise, so a kept
# loopback URL can never be mistaken for the funnel host.
_uri_host() {
  local u="${1#*://}"
  u="${u%%/*}"
  # Bracketed IPv6 first: a bare `%%:*` would truncate `[::1]:8001` to `[`.
  if [[ "$u" == \[* ]]; then
    u="${u#[}"
    u="${u%%\]*}"
  else
    u="${u%%:*}"
  fi
  _valid_tsdns "$u" || return 1
  printf '%s' "$u"
}

# _valid_fqdn mirrors the server's validRedirectHost for https: dotted
# FQDN, lowercase alnum/hyphen labels, no leading/trailing hyphen, TLD of
# 2+ letters (custom domains, nip.io — not just tailnet). The input must
# already be lowercased (canonical form); this checks shape, not case.
_valid_fqdn() {
  local host="$1" label tld
  local -a labels
  [[ -n "$host" ]] || return 1
  (( ${#host} <= 253 )) || return 1
  [[ "$host" == "localhost" ]] && return 0
  [[ "$host" == *.* ]] || return 1
  IFS=. read -ra labels <<< "$host" || return 1
  for label in "${labels[@]}"; do
    (( ${#label} >= 1 && ${#label} <= 63 )) || return 1
    [[ "$label" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?$ ]] || return 1
  done
  tld="${labels[${#labels[@]}-1]}"
  if [[ "$tld" == xn--* ]]; then
    # Punycode carve-out like the server: the suffix is encoded Unicode,
    # validated by the label rules above — except a bare `xn--` prefix.
    [[ "$tld" == "xn--" ]] && return 1
  else
    [[ "$tld" =~ ^[a-z][a-z]+$ ]] || return 1
  fi
  # Reserved + private-use TLDs can never hold a public registration
  # (RFC-2606, mDNS, unqualified-LAN, special-use — server parity list).
  case "$tld" in
    test|example|invalid|local|internal|lan|home|corp|localdomain|intranet|onion|arpa) return 1;;
  esac
  # `*.localhost` / `localhost.*`: unregistrable both directions (only
  # bare `localhost` passes, handled by the caller).
  case "$host" in *.localhost|localhost.*) return 1;; esac
  return 0
}

# _clean_path prints the path.Clean equivalent of an absolute path:
# collapse // runs, resolve /./ and /x/../ (leading /.. stays at root,
# like Clean). The server Cleans before comparing/sending, so printing
# anything else as "exact string to register" mismatches its bytes.
_clean_path() {
  local p="$1" seg
  local -a out=()
  while [[ "$p" == *//* ]]; do p="${p//\/\//\/}"; done
  local IFS=/
  local -a segs=()
  read -ra segs <<< "$p" || true
  for seg in "${segs[@]}"; do
    case "$seg" in
      ""|.) continue ;;
      ..)
        if (( ${#out[@]} > 0 )); then
          unset 'out[${#out[@]}-1]'
        fi
        ;;
      *) out+=("$seg") ;;
    esac
  done
  if (( ${#out[@]} == 0 )); then
    printf '/'
  elif (( ${#out[@]} == 1 )); then
    # Single segment: the second printf below would emit a bare `/`
    # (missing %s arg prints the literal), so skip it — `/b` stays `/b`.
    printf '/%s' "${out[0]}"
  else
    printf '/%s' "${out[0]}"
    printf '/%s' "${out[@]:1}"
  fi
}

# canonical_redirect_uri prints the canonical form of a redirect URI the
# way the server sends it: lowercased host, no trailing dot, no default
# port (numeric compare, so :080/:0443 strip like :80/:443), non-default
# ports kept, one trailing slash trimmed. Google
# exact-matches the sent bytes, so registering this string (or comparing
# the startup-log line against it) is the only correct comparison — the
# input spelling may differ while sending identically. Bracketed IPv6
# hosts survive intact; a malformed value prints unchanged (validated
# by the caller, never here). Deliberately NOT full server parity: query,
# fragment, userinfo, encodings, and path case are refused outright by the
# server, so the final block rejects those shapes instead of normalising
# them.
canonical_redirect_uri() {
  local u="$1" scheme rest path hostport host port
  [[ "$u" == *://* ]] || { printf '%s' "$u"; return 0; }
  scheme="${u%%://*}"
  # Lowercased like the server (url.Parse folds it): an uppercase scheme
  # sends lowercase, so registering the input spelling mismatches.
  scheme=$(printf '%s' "$scheme" | tr '[:upper:]' '[:lower:]')
  rest="${u#*://}"
  if [[ "$rest" == */* ]]; then
    path="/${rest#*/}"
    hostport="${rest%%/*}"
  else
    path="/"
    hostport="$rest"
  fi
  # Server path.Clean parity (interior //, /./, /x/../): the server sends
  # the cleaned form, so the printed string must be cleaned too — a dirty
  # path kept verbatim would mismatch its bytes. Deliberately NOT covered:
  # query, fragment, userinfo, encodings, and path case are refused
  # outright by the server, so the final block rejects those shapes instead
  # of normalising them.
  path="$(_clean_path "$path")"
  if [[ "$hostport" == \[*\]* ]]; then
    host="${hostport%%\]*}]"
    port="${hostport#*]}"
    port="${port#:}"
  else
    host="${hostport%%:*}"
    if [[ "$host" == "$hostport" ]]; then
      port=""
    else
      port="${hostport##*:}"
      # Dangling colon (host: with no port) is preserved verbatim for the
      # final gate to reject: dropping it would print a different URL than
      # pasted, and the server 501s it ("port must be numeric").
      if [[ -z "$port" ]]; then printf '%s' "$u"; return 0; fi
    fi
  fi
  host=$(printf '%s' "$host" | tr '[:upper:]' '[:lower:]')
  # Loop-strip like the server TrimRight: h.ts.net.. sends dot-less.
  while [[ "$host" == *. ]]; do host="${host%.}"; done
  if [[ "$port" =~ ^[0-9]+$ ]]; then
    # Numeric compare AND normalization: :080 sends as :80, so the
    # canonical form strips the padding but keeps a non-default port.
    port="$((10#$port))"
    if { [[ "$scheme" == "https" ]] && (( port == 443 )); } || \
       { [[ "$scheme" == "http" ]] && (( port == 80 )); }; then
      port=""
    fi
  fi
  if [[ -n "$port" ]]; then
    host="$host:$port"
  fi
  printf '%s://%s%s' "$scheme" "$host" "$path"
}

REPO_DIR="${REPO_DIR:-}"
if [[ -z "$REPO_DIR" ]]; then
  # Follow symlinks first: an `ln -s …/connectors-google-setup.sh` on PATH
  # otherwise resolves the link's directory and targets the wrong checkout
  # for the .env default and the absolute checklist path. Portable loop
  # (BSD readlink has no -f), bounded so a symlink cycle can't hang.
  # No `--` on dirname/readlink: BSD rejects it, and these operands come
  # from BASH_SOURCE, never a dash-leading path.
  _self="${BASH_SOURCE[0]}"; _hops=0
  while [[ -L "$_self" ]] && (( _hops < 40 )); do
    _link_dir=$(cd -- "$(dirname "$_self" 2>/dev/null)" 2>/dev/null && pwd) || break
    _target=$(readlink "$_self" 2>/dev/null) || break
    [[ "$_target" == /* ]] || _target="$_link_dir/$_target"
    _self="$_target"; _hops=$((_hops + 1))
  done
  REPO_DIR=$(cd "$(dirname "$_self" 2>/dev/null)/.." 2>/dev/null && pwd) || REPO_DIR=""
  unset _self _hops _link_dir _target
fi
# An empty REPO_DIR would resolve ENV_FILE to "/.env" (absolute, so the
# relative-canonicalization below skips it) and misdirect stage 8 — or,
# as root, create /.env. The cd fails only on a moved/deleted tree, but
# fail loud regardless.
if [[ -z "$REPO_DIR" ]]; then
  warn "cannot resolve the repo root from this script's path — re-run from a clean checkout"
  exit 1
fi
# ${ENV_FILE:-...} keeps the library contract: callers (and dry-run renders
# against a throwaway copy) can point it elsewhere.
ENV_FILE="${ENV_FILE:-$REPO_DIR/.env}"
# The library already defaulted ENV_FILE to the relative ".env" at load, so
# the :- above never fires on a normal run — normalize that exact default to
# the repo root, or running from /tmp reads /tmp/.env and stage 8 exits.
# Strip one leading "./" first: ./.env is the same file as .env, and without
# this it would take the override branch in the stage-8 hint.
while [[ "$ENV_FILE" == ./* ]]; do ENV_FILE="${ENV_FILE#./}"; done
if [[ "$ENV_FILE" == ".env" ]]; then ENV_FILE="$REPO_DIR/.env"; fi
# Tilde never expands inside a variable value: ~/x would canonicalize to
# $PWD/~/x below. Expand a leading ~ (or bare ~) against $HOME first.
if [[ "$ENV_FILE" == "~" ]]; then
  [[ -n "${HOME:-}" ]] || { warn "HOME is unset — export HOME or pass an absolute ENV_FILE"; exit 1; }
  ENV_FILE="$HOME"
fi
# Literal-tilde match is the point below; the expansion SC2088 wants is
# exactly what the assignment implements.
# shellcheck disable=SC2088
if [[ "$ENV_FILE" == "~/"* ]]; then
  [[ -n "${HOME:-}" ]] || { warn "HOME is unset — export HOME or pass an absolute ENV_FILE"; exit 1; }
  ENV_FILE="$HOME/${ENV_FILE#"~/"}"; fi
# ~user expansion is a login-shell feature we do not implement; fail loud
# rather than canonicalizing it into "$PWD/~user/…" and misdirecting stage 8.
if [[ "$ENV_FILE" == "~"* ]]; then
  warn "ENV_FILE only expands bare ~ and ~/… — pass an absolute path"
  exit 1
fi
# An explicit relative export (ENV_FILE=throwaway.env) would otherwise
# split-brain: stage 8 writes against the caller's cwd while the render
# cd's to REPO_DIR first. Canonicalize once, against the invoking cwd.
if [[ "$ENV_FILE" != /* ]]; then ENV_FILE="$PWD/$ENV_FILE"; fi
TS_HOST="${TS_HOST:-}"  # defaulted to hostname -s in stage 3, after the hostname preflight below
TS_DNS="${TS_DNS:-}"          # <name>.<tailnet>.ts.net, no trailing dot
REDIRECT_URI="${REDIRECT_URI:-}"  # preset honoured; empty means derive from TS_DNS below
_redirect_preset="${REDIRECT_URI:-}"

banner "Google connectors over Tailscale Funnel"

# Proxy host port follows APP_PORT (compose default 8080): every funnel
# target, probe, and status match below must use it, or a custom-port
# deploy funnels to a dead port while the wizard reports green. Shell env
# wins over .env, matching compose precedence. Non-numeric or out-of-range
# values fail loudly with the winning source named — a silent default here
# would funnel to a port compose does not serve. Same treatment for the
# health-api direct mapping below (HEALTH_HOST_PORT, compose default 8001):
# a loopback REDIRECT_URI on any other port must warn, not probe dead air.
_proxy_port="${APP_PORT:-}"
_proxy_port_src="shell APP_PORT"
if [[ -z "$_proxy_port" ]]; then
  _proxy_port=$(_existing APP_PORT 2>/dev/null || true)
  _proxy_port_src="root .env APP_PORT"
fi
if [[ -z "$_proxy_port" ]]; then
  # Unset everywhere: compose defaults to 8080, so do we — quietly.
  # Only an explicitly set but invalid value exits below.
  _proxy_port="8080"
  _proxy_port_src="compose default"
fi
if [[ ${#_proxy_port} -gt 5 ]] || [[ ! "$_proxy_port" =~ ^[0-9]+$ ]] || (( 10#$_proxy_port < 1 || 10#$_proxy_port > 65535 )); then
  warn "APP_PORT is not numeric 1-65535 (from $_proxy_port_src: '${_proxy_port:-<empty>}') — fix it, do not proceed on a default:"
  warn "funnelling to a silently-defaulted port serves a URL nothing answers."
  exit 1
fi
_proxy_target="http://127.0.0.1:$_proxy_port"
# Direct-loopback health-api port, same precedence (shell → .env →
# compose-default 8001). A loopback REDIRECT_URI naming any other port
# fails the loopback-host/port cross-check below with a pointer here.
_health_port="${HEALTH_HOST_PORT:-}"
_health_port_src="shell HEALTH_HOST_PORT"
if [[ -z "$_health_port" ]]; then
  _health_port=$(_existing HEALTH_HOST_PORT 2>/dev/null || true)
  _health_port_src="root .env HEALTH_HOST_PORT"
fi
if [[ -z "$_health_port" ]]; then
  _health_port="8001"
  _health_port_src="compose default"
fi
if [[ ${#_health_port} -gt 5 ]] || [[ ! "$_health_port" =~ ^[0-9]+$ ]] || (( 10#$_health_port < 1 || 10#$_health_port > 65535 )); then
  warn "HEALTH_HOST_PORT is not numeric 1-65535 (from $_health_port_src: '${_health_port:-<empty>}') — fix it, do not proceed on a default."
  exit 1
fi

# ── Stage 1: preflight ────────────────────────────────────────────────────
stage "Preflight: what this will change"
say "This sets up the OAuth callback for the Gmail/Calendar connectors."
say "Plan: Tailscale Funnel terminates public TLS on 443 and forwards to the"
say "      existing nginx proxy on $_proxy_target. No ports are opened, no"
say "      domain is bought. The app keeps its current Server URL."
say "      Note: the funnel publishes the whole proxy (chat + sync stay"
say "      PASSWORD-gated); the OAuth callback is the only new unauthenticated"
say "      API surface (static liveness /health and /ping, plus pi liveness"
say "      /p/healthz[/], ride along). Do not share the *.ts.net URL."
printf '\n'
say "What is on disk right now:"
for k in GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET GOOGLE_REDIRECT_URL CONNECTORS_ENCRYPTION_KEY; do
  if v=$(_existing "$k" 2>/dev/null) && [[ -n "$v" ]]; then note "  $k: set"
  else note "  $k: MISSING"; fi
done
unset v
say "  tailscale: $(command -v tailscale >/dev/null 2>&1 && echo installed || echo 'not installed')"
if curl -fsS --max-time 5 "$_proxy_target/ping" >/dev/null 2>&1; then
  note "  proxy :$_proxy_port: listening"
else
  note "  proxy :$_proxy_port: NOT answering (/ping)"
  warn "the funnel forwards to this proxy — a stopped stack means minutes"
  warn "of stage-3/4 waits before anything fails. Start the stack first"
  warn "(./scripts/hermes.sh start) or continue anyway."
  # confirm takes ^[Yy] (library, template-level), so a "yn" typo reads
  # yes. Asymmetry with stage 5 is deliberate: a mis-skip here costs
  # minutes of waits, while there it would burn the create-project flow.
  if ! confirm "Continue without a listening proxy?"; then
    say "Stopped. Nothing changed."
    exit 1
  fi
fi
# Dependency preflight: every external the stages shell out to that must
# exist. jq is the critical one — without it every tailscale-status check
# misreads as down. Deliberately unlisted: ps (has a kill -0 fallback),
# readlink (symlink resolution degrades to the script's own directory),
# tput (colors degrade), timeout (documented optional), grep/sed/tr/cut/
# head/sleep and dirname (universal).
# Local-daemon calls (tailscale over its unix socket) are intentionally
# unbounded throughout: a wedged daemon fails fast in practice, unlike
# network waits, which all carry budgets (curl --max-time, loop counts,
# timeout wrappers).
# (tailscale itself is installed in stage 2, so its absence here is expected.)
_missing=""
for _dep in jq openssl curl podman podman-compose hostname date; do
  if ! command -v "$_dep" >/dev/null 2>&1; then _missing="${_missing:+$_missing }$_dep"; fi
done
unset _dep
if [[ -n "$_missing" ]]; then
  warn "missing: ${_missing} — install them, then re-run"
  exit 1
fi
unset _missing
if [[ "${EUID:-$(id -u 2>/dev/null || true)}" -ne 0 ]]; then
  warn "not running as root: tailscale install/up/funnel typically need root"
  warn "(upstream examples use 'sudo tailscale ...'). Re-run with sudo if"
  warn "those steps fail."
  if ! confirm "Continue as non-root?"; then
    say "Stopped. Nothing changed."
    exit 1
  fi
fi
printf '\n'
note "This host is the live stack. Writing .env is safe (inert until the"
note "containers are recreated — ./scripts/hermes.sh restart recreates them;"
note "a plain container restart without recreation will not pick up .env)."
note "Nothing is restarted by this wizard."
note "Dry-run knobs (all optional): TS_DNS presets skip discovery and the"
note "probe wait, REDIRECT_URI presets skip derivation (and set the recorded"
note "comment host), TS_HOST presets skip the hostname default, ENV_FILE"
note "points at another file, SKIP_PROBE=1 skips the wait."
printf '\n'
if ! confirm "Proceed with Tailscale Funnel setup on this host?"; then
  say "Stopped. Nothing changed."
  exit 1
fi

# ── Stage 2: install ──────────────────────────────────────────────────────
stage "Install Tailscale"
if command -v tailscale >/dev/null 2>&1; then
  note "already installed: $(tailscale version 2>/dev/null | head -n1 2>/dev/null || true)"
else
  _codename=""
  if [[ -f /etc/os-release ]]; then
    _codename=$(sed -n 's/^VERSION_CODENAME=//p' /etc/os-release 2>/dev/null | tr -d '"' 2>/dev/null || true)
  fi
  say "Installing from Tailscale's official apt repo${_codename:+ (Ubuntu $_codename)}."
  unset _codename
  note "This adds /etc/apt/sources.list.d/tailscale.list and the tailscaled service."
  printf '\n'
  # The stage-1 EUID gate lets non-root continue; the install itself cannot
  # succeed without root, so stop here instead of burning a doomed download.
  if [[ "${EUID:-$(id -u 2>/dev/null || true)}" -ne 0 ]]; then
    warn "cannot install as non-root — re-run with sudo, then re-run this wizard"
    exit 1
  fi
  if ! confirm "Install Tailscale now?"; then
    warn "skipped install; re-run this wizard when ready"
    exit 1
  fi
  # Intentionally the upstream installer (no pinning): Tailscale's documented
  # install path; the repo otherwise avoids pipe-to-shell for its own code.
  curl -fsSL https://tailscale.com/install.sh | sh || {
    warn "Tailscale download/install failed (network?). Re-run the wizard when it works."
    exit 1
  }
  printf '\n'
  printf '  %s✓%s installed %s\n' "$GREEN" "$RESET" "$(tailscale version 2>/dev/null | head -n1 2>/dev/null || true)"
fi
if command -v systemctl >/dev/null 2>&1; then
  say "Service: $(systemctl is-active tailscaled 2>/dev/null || true)"
else
  note "systemctl absent (non-systemd host); tailscaled state unchecked"
fi

# ── Stage 3: join the tailnet ─────────────────────────────────────────────
stage "Join your tailnet"
if tailscale status --json 2>/dev/null | jq -e '.BackendState == "Running"' >/dev/null 2>&1; then
  note "already connected"
  TS_HOST=$(tailscale status --json 2>/dev/null | jq -r '.Self.HostName // empty' 2>/dev/null || true)
else
  say "The machine name becomes the public hostname: <name>.<tailnet>.ts.net"
  step "Pick a short lowercase name (letters, digits, hyphen)."
  note "This name is re-asked each run (only the .env values persist) — after"
  note "a successful join, re-runs take the already-connected path instead."
  # ask's Enter-keeps-current reads ENV_FILE, where TS_HOST never lives —
  # so remember an env preset explicitly instead of losing it to hostname -s.
  _ts_preset="${TS_HOST:-}"
  # Computed once: hostname -s can emit a dotted FQDN on minimal images —
  # cut to the first label so the strict regex below doesn't loop-reject
  # the default.
  _host_default=$(hostname -s 2>/dev/null | cut -d. -f1 2>/dev/null || true)
  # An unset hostname yields an empty default, an empty fallback, and a
  # regex that rejects empty — an endless warn loop with no way forward
  # except Ctrl-C. Fail fast instead.
  if [[ -z "$_ts_preset" && -z "$_host_default" ]]; then
    warn "hostname is empty and no TS_HOST preset — set the hostname or export TS_HOST, then re-run"
    exit 1
  fi
  while true; do
    ask TS_HOST "Machine name [${TS_HOST:-$_host_default}]:" || { warn "no input — the wizard needs a terminal; re-run to try again"; exit 1; }
    # Pasted hostnames trail whitespace like stage-7 pastes, so trim the
    # *edges* — but not interior whitespace: "my host" is a typo the strict
    # regex must reject, not silently repair into "myhost".
    TS_HOST="${TS_HOST#"${TS_HOST%%[![:space:]]*}"}"
    TS_HOST="${TS_HOST%"${TS_HOST##*[![:space:]]}"}"
    TS_HOST="${TS_HOST:-${_ts_preset:-$_host_default}}"
    if [[ "$TS_HOST" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?$ ]]; then break; fi
    warn "invalid: use lowercase letters, digits, hyphens (no leading/trailing hyphen)"
    TS_HOST=""; _ts_preset=""
  done
  unset _ts_preset _host_default
  printf '\n'
  say "Opening a login URL. Sign in with your Tailscale account (creating one"
  say "on the free Personal plan is fine) and approve this machine."
  printf '\n'

  LOG=$(mktemp) || { warn "temp file creation failed (TMPDIR full?) — re-run when /tmp is writable"; exit 1; }
  tailscale up --hostname="$TS_HOST" </dev/null >"$LOG" 2>&1 &
  TS_PID=$!
  URL=""
  # Current login-URL shape, Tailscale SaaS control plane only — a Headscale
  # URL won't match and takes the 60s fallback. Same fallback covers a
  # Tailscale-side domain change.
  for ((__i = 1; __i <= 60; __i++)); do
    URL=$(grep -oE -- 'https://login\.tailscale\.com/[^[:space:]]+' "$LOG" 2>/dev/null | head -n1 2>/dev/null || true)
    if [[ -n "$URL" ]]; then
      # The writer appends concurrently, so a match can be a half-flushed
      # line. Require the same URL on a second read before opening it —
      # one extra second, never a truncated browser open.
      sleep 1
      _url2=$(grep -oE -- 'https://login\.tailscale\.com/[^[:space:]]+' "$LOG" 2>/dev/null | head -n1 2>/dev/null || true)
      if [[ -n "$_url2" && "$_url2" == "$URL" ]]; then break; fi
      URL=""
    fi
    _alive "$TS_PID" || break
    printf '%s' '.'; sleep 1
  done
  unset _url2
  printf '\n'
  if [[ -n "$URL" ]]; then
    open_url "$URL"
    pause "Press Enter once you've approved the machine in the browser."
  else
    warn "no login URL appeared; output so far:"
    sed 's/^/      /' "$LOG" 2>/dev/null || true
    pause "Fix the above, then press Enter to check again."
  fi
  # Last read: a one-time login URL must not ride in memory through the
  # funnel wait, the probe and the .env writes.
  unset URL
  # If the setup process already exited (bad hostname, no root, daemon down),
  # the wait below can never succeed — check state once and fall through to
  # the "not Running yet" exit instead of two minutes of dots.
  _up_alive=0
  if _alive "$TS_PID"; then _up_alive=1; fi
  if (( _up_alive == 0 )) && ! tailscale status --json 2>/dev/null | jq -e '.BackendState == "Running"' >/dev/null 2>&1; then
    note "setup process already exited and daemon not Running — skipping the wait"
  else
    for ((__i = 1; __i <= 60; __i++)); do
      tailscale status --json 2>/dev/null | jq -e '.BackendState == "Running"' >/dev/null 2>&1 && break
      printf '%s' '.'; sleep 2
    done
    printf '\n'
  fi
  unset _up_alive
  # `tailscale up` exits once the node is up, so by the time Running is
  # confirmed it is already reaped-or-reapable: this wait returns at once
  # in every normal flow and only exists so the EXIT trap can never fire
  # on a recycled PID. Deliberately unbounded: bounding a wait(1) builtin
  # takes a killer-watchdog the latency doesn't justify — a `up` that
  # lingers post-connect is doing work the wizard should wait for, not
  # outrun. (Already-connected takes this path with TS_PID empty — hence
  # the guard, since wait on "" is only accidentally harmless.)
  if [[ -n "$TS_PID" ]] && tailscale status --json 2>/dev/null | jq -e '.BackendState == "Running"' >/dev/null 2>&1; then
    wait "$TS_PID" 2>/dev/null || true
    TS_PID=""
  fi
  # Clear the log path alongside the file itself so the trap goes quiet.
  # || true: the EXIT trap owns these paths, so cleanup failure must not
  # exit silently with set -e (same rule as the render tmps below).
  rm -f "$LOG" || true; LOG=""
fi

if ! tailscale status --json 2>/dev/null | jq -e '.BackendState == "Running"' >/dev/null 2>&1; then
  warn "tailscaled is not Running yet. Re-run the wizard when it is."
  tailscale status || true
  exit 1
fi

# TS_DNS honours a caller preset (dry-runs) instead of silently discarding
# it — same contract as ENV_FILE. Empty means discover from the daemon.
_DNS_FROM_PRESET=0
_URI_FROM_PRESET=0
if [[ -n "$TS_DNS" ]]; then
  # The daemon path strips one trailing dot before validating; do the same
  # for presets so the same string passes either way.
  TS_DNS="${TS_DNS%.}"
  # Presets are trusted for dry-runs but not for sed: validate the shape
  # before it reaches the stage-8 hostname refresh (|/&/newline injection).
  # Same strictness as TS_HOST, label by label (a typo like -foo..ts.net
  # must fail here, not at the probe in stage 4).
  if ! _valid_tsdns "$TS_DNS"; then
    warn "preset TS_DNS=$TS_DNS is not a <name>.<tailnet>.ts.net hostname; unset it to discover from the daemon"
    exit 1
  fi
  note "using preset TS_DNS=$TS_DNS (skipping discovery)"
  _DNS_FROM_PRESET=1
else
  TS_DNS=$(tailscale status --json 2>/dev/null | jq -r '.Self.DNSName // empty' 2>/dev/null | sed 's/\.$//' 2>/dev/null || true)
fi
# (no "null" check: jq -r ... // empty never emits the literal string.)
if [[ -z "$TS_DNS" ]]; then
  warn "could not read the tailnet DNS name (is MagicDNS enabled?)"
  exit 1
fi
# Defense in depth: the daemon is trusted, but the value feeds the same
# three sinks the preset guards protect (REDIRECT_URI derivation, the
# stage-8 sed refresh, s_client) — and this also fail-fasts truncated
# MagicDNS-off output at the same point as typos.
if ! _valid_tsdns "$TS_DNS"; then
  warn "daemon-reported TS_DNS=$TS_DNS is not a <name>.<tailnet>.ts.net hostname; check MagicDNS, then re-run"
  exit 1
fi
printf '\n'
printf '  %s✓%s %s\n' "$GREEN" "$RESET" "https://$TS_DNS"

if [[ -n "$_redirect_preset" ]]; then
  # Same treatment as the TS_DNS preset: write_env single-quote-escapes but
  # does not stop newlines, so a multiline preset would write a second line
  # into .env. read-based input can't contain one — only presets can.
  # Host part validated label by label, like TS_DNS above. Scheme folded
  # for matching (server lowercases it); the canonical form is stored.
  # Accepts https tailnet/FQDN presets AND the documented http-loopback
  # testing shape (.env.example) — both of which the final gate passes,
  # so rejecting either here would contradict it.
  _preset_fold="$(printf '%s' "${_redirect_preset%%://*}" | tr '[:upper:]' '[:lower:]')://${_redirect_preset#*://}"
  _uri_host=""
  _preset_ok=0
  if [[ "$_preset_fold" == https://*/api/connectors/callback ]]; then
    # Canonicalise before validating: an explicit :443, uppercase host,
    # or trailing dot sends identically but must not fail validation —
    # and the canonical form is what gets stored and registered.
    _redirect_preset="$(canonical_redirect_uri "$_redirect_preset")"
    # Derive the host from the canonicalised value (not the scheme-only
    # fold): uppercase hosts and trailing dots canonicalise to a valid
    # tailnet name, and validating the raw spelling would exit 1 on a URL
    # that sends identically.
    _uri_host="${_redirect_preset#https://}"
    _uri_host="${_uri_host%/api/connectors/callback}"
    _uri_host="${_uri_host%%:*}"
    if _valid_tsdns "$_uri_host" 2>/dev/null || _valid_fqdn "$_uri_host" 2>/dev/null; then
      _preset_ok=1
    fi
  elif [[ "$_preset_fold" == http://*/api/connectors/callback ]]; then
    _redirect_preset="$(canonical_redirect_uri "$_redirect_preset")"
    _uri_host="${_redirect_preset#http://}"
    _uri_host="${_uri_host%/api/connectors/callback}"
    if [[ "$_uri_host" == \[* ]]; then
      _uri_host="${_uri_host#[}"; _uri_host="${_uri_host%%\]*}"
    else
      _uri_host="${_uri_host%%:*}"
    fi
    case "$_uri_host" in localhost|127.0.0.1|::1) _preset_ok=1;; esac
  fi
  if (( ! _preset_ok )); then
    warn "preset REDIRECT_URI is not a registrable https tailnet/FQDN or http loopback .../api/connectors/callback URL; unset it to derive from TS_DNS"
    exit 1
  fi
  unset _uri_host _preset_fold _preset_ok
  REDIRECT_URI="$_redirect_preset"
  _URI_FROM_PRESET=1
  note "using preset REDIRECT_URI (skipping derivation from TS_DNS)"
else
  REDIRECT_URI="https://$TS_DNS/api/connectors/callback"
  _URI_FROM_PRESET=0
fi
unset _redirect_preset
# The knobs are independent, so they can contradict: funnel serves TS_DNS
# while Google registers the URI host. Both can be legitimate (dry-runs),
# but a silent split funnels A while registering B — warn, don't stop.
# Compared *after* the keep prompt below, since keeping can replace the URI;
# a warn placed here would describe a value that is no longer registered.
# Every other captured value offers keep-current on re-runs; the derived
# URI must too, or a hand-customized URL (e.g. loopback for local testing)
# is silently overwritten. Identical re-derivations stay silent — the
# prompt fires only on an actual difference.
if _recorded_uri=$(_existing GOOGLE_REDIRECT_URL 2>/dev/null) && [[ -n "$_recorded_uri" && "$_recorded_uri" != "$REDIRECT_URI" ]]; then
  warn "recorded GOOGLE_REDIRECT_URL differs from the derived one:"
  warn "  recorded: $_recorded_uri"
  warn "  derived:  $REDIRECT_URI"
  # A stale/typo'd entry must not sail through on keep while a deliberate
  # non-standard URL (loopback for local testing) must survive: validate
  # first, then tailor the question. Strict-pass keeps quietly offerable;
  # strict-fail keeps only via an explicit knowingly-keep.
  _rec_host=""
  # Match on a scheme-folded copy (the server lowercases the scheme, so an
  # uppercase-scheme recorded value is the same URL); convert/store from
  # the original, and the final canonicalisation normalizes the case.
  _rec_fold="$(printf '%s' "${_recorded_uri%%://*}" | tr '[:upper:]' '[:lower:]')://${_recorded_uri#*://}"
  # The /p/ spelling is checked FIRST: glob `*` spans `/`, so it would
  # also match the bare pattern below and skip conversion entirely.
  if [[ "$_rec_fold" == https://*/p/api/connectors/callback ]]; then
    # Pre-#488 spelling pointed at pi-gateway, which still serves it until
    # the #494 teardown — but health-api (the future) does not, so offer
    # the same host bare. Declining falls through to the typo path
    # below, which names the mismatch and offers a knowingly-keep.
    _bare="${_recorded_uri%/p/api/connectors/callback}/api/connectors/callback"
    warn "recorded URL uses the retired /p/ spelling (pi-gateway still serves it until the #494 teardown; health-api does not):"
    warn "  recorded: $_recorded_uri"
    warn "  bare:     $_bare"
    if confirm "Switch to the bare URL (re-register it in the Google console)?"; then
      REDIRECT_URI="$_bare"
      note "keeping converted REDIRECT_URI (tailnet rename? re-check the Google console registration)"
      _rec_host=$(_uri_host "$_bare" || true)
      _converted=1
    else
      _rec_host=""
    fi
    unset _bare
  elif [[ "$_rec_fold" == https://*/api/connectors/callback ]]; then
    # Same host derivation as probe/comment: scheme- and port-agnostic,
    # so an explicit `:443` spelling (same canonical form) passes here too.
    # Tailnet OR any valid FQDN (custom domains, nip.io) — the final gate
    # enforces the same pair, so a recorded custom-domain URL strict-passes
    # here instead of falling into the typo branch.
    _rec_host=$(_uri_host "$_recorded_uri" || true)
    if [[ -z "$_rec_host" ]]; then
      _rec_host_bare="${_recorded_uri#*://}"
      _rec_host_bare="${_rec_host_bare%%/*}"
      if [[ "$_rec_host_bare" == \[*\]* ]]; then
        _rec_host_bare="${_rec_host_bare#[}"
        _rec_host_bare="${_rec_host_bare%%\]*}"
      else
        _rec_host_bare="${_rec_host_bare%%:*}"
      fi
      # Lowercased for the check only: the final canonicalisation folds
      # case, so an uppercase host must not fail here.
      _rec_host_bare="$(printf '%s' "$_rec_host_bare" | tr '[:upper:]' '[:lower:]')"
      _valid_fqdn "$_rec_host_bare" 2>/dev/null && _rec_host="$_rec_host_bare"
      unset _rec_host_bare
    fi
  elif [[ "$_rec_fold" == http://*/api/connectors/callback ]]; then
    # Documented loopback testing shape: like the preset gate, http passes
    # for loopback hosts only — anything else falls to the typo branch.
    _rec_host_bare="${_recorded_uri#*://}"
    _rec_host_bare="${_rec_host_bare%%/*}"
    if [[ "$_rec_host_bare" == \[*\]* ]]; then
      _rec_host_bare="${_rec_host_bare#[}"
      _rec_host_bare="${_rec_host_bare%%\]*}"
    else
      _rec_host_bare="${_rec_host_bare%%:*}"
    fi
    _rec_host_bare="$(printf '%s' "$_rec_host_bare" | tr '[:upper:]' '[:lower:]')"
    case "$_rec_host_bare" in localhost|127.0.0.1|::1) _rec_host="$_rec_host_bare";; esac
    unset _rec_host_bare
  fi
  if [[ -n "${_converted:-}" ]]; then
    : # converted above; nothing left to keep or question.
  elif [[ -n "$_rec_host" ]]; then
    if confirm "Keep the recorded URL?"; then
      REDIRECT_URI="$_recorded_uri"
      note "keeping recorded REDIRECT_URI (tailnet rename? re-check the Google console registration)"
    fi
  else
    warn "recorded URL fails the expected shape (https://<host>.<tailnet>.ts.net/api/connectors/callback)"
    warn "typo? keeping it registers a URL Google will never call back to."
    if confirm "Keep it anyway (only for deliberate non-standard setups)?"; then
      REDIRECT_URI="$_recorded_uri"
      note "keeping non-standard recorded REDIRECT_URI as chosen"
      note "the probe below hits this kept URL verbatim, and the .env comment records its host"
    fi
  fi
  unset _rec_host _converted _rec_fold
fi
# Canonicalise the final value before probing, printing, and writing:
# Google exact-matches the sent bytes, and the server sends the canonical
# form — so the .env value, the printed string, and the probe target must
# all be canonical, or the wizard recommends a URL that mismatches.
_canon_uri="$(canonical_redirect_uri "$REDIRECT_URI")"
if [[ "$_canon_uri" != "$REDIRECT_URI" ]]; then
  note "canonicalised REDIRECT_URI for registration (this is the sent bytes):"
  note "  was: $REDIRECT_URI"
  note "  now: $_canon_uri"
  REDIRECT_URI="$_canon_uri"
fi
unset _canon_uri
# Exactness the canonicaliser deliberately does not provide: query,
# fragment, userinfo, percent-encodings, and path case are refused
# outright by the server (501), so they must fail here with a pointer —
# never sail into .env and die as redirect_uri_mismatch.
_canonical_rest="${REDIRECT_URI#*://}"
_canonical_path="/${_canonical_rest#*/}"
if [[ "$REDIRECT_URI" == *\?* || "$REDIRECT_URI" == *\#* || "$REDIRECT_URI" == *@* || "$REDIRECT_URI" == *%* ]]; then
  warn "REDIRECT_URI carries a query, fragment, userinfo, or percent-encoding — the server refuses all four (501)."
  warn "  value: $REDIRECT_URI"
  warn "Re-run with a clean https://<host>/api/connectors/callback value, or keep knowingly:"
  if ! confirm "Keep it anyway (registration will mismatch)?"; then exit 1; fi
elif [[ "$_canonical_path" != "/api/connectors/callback" ]]; then
  warn "REDIRECT_URI path is not exactly /api/connectors/callback (case-sensitive, no trailing slash — canonicalisation already trimmed one):"
  warn "  value: $REDIRECT_URI"
  warn "Re-run with the exact path, or keep knowingly:"
  if ! confirm "Keep it anyway (registration will mismatch)?"; then exit 1; fi
fi
unset _canonical_path _canonical_rest
# Port gate: the server requires digits-only 1-65535 (parsePort) — a
# non-numeric or out-of-range port 501s, so it must fail here with a
# pointer at the startup-log line, not print as registrable. Empty
# (default port) passes; brackets handled like the TLS branch.
_final_port_from_uri="${REDIRECT_URI#*://}"
_final_port_from_uri="${_final_port_from_uri%%/*}"
if [[ "$_final_port_from_uri" == \[*\]* ]]; then
  _final_port_from_uri="${_final_port_from_uri#*]}"
  _final_port_from_uri="${_final_port_from_uri#:}"
else
  case "$_final_port_from_uri" in
    *:* ) _final_port_from_uri="${_final_port_from_uri##*:}" ;;
    * ) _final_port_from_uri="" ;;
  esac
fi
if [[ -n "$_final_port_from_uri" ]]; then
  # Length gate first: arithmetic on a 100-digit string wraps, so cap at
  # 5 digits (65535 max) before the numeric compare.
  if [[ ${#_final_port_from_uri} -gt 5 ]] || [[ ! "$_final_port_from_uri" =~ ^[0-9]+$ ]] || (( 10#$_final_port_from_uri < 1 || 10#$_final_port_from_uri > 65535 )); then
    warn "REDIRECT_URI port is not numeric 1-65535 (server fails it closed):"
    warn "  value: $REDIRECT_URI"
    warn "Re-run with a valid port, or keep knowingly:"
    if ! confirm "Keep it anyway (registration will mismatch)?"; then exit 1; fi
  fi
fi
unset _final_port_from_uri
# Funnel serves 443 only: a funnel-host URI carrying any other explicit
# port registers a string the funnel never delivers (Google redirects to
# :8443 while only :443 answers). Custom hosts need their own serving
# regardless — this gate is strictly about the funnel host + wrong port.
_funnel_hp="${REDIRECT_URI#*://}"
_funnel_hp="${_funnel_hp%%/*}"
if [[ "$_funnel_hp" == \[*\]* ]]; then
  _funnel_hp="${_funnel_hp#[}"
  _funnel_hp="${_funnel_hp%%\]*}"
else
  _funnel_hp="${_funnel_hp%%:*}"
fi
_funnel_hp="$(printf '%s' "$_funnel_hp" | tr '[:upper:]' '[:lower:]')"
_funnel_ts="$(printf '%s' "$TS_DNS" | tr '[:upper:]' '[:lower:]')"
if [[ -n "$_funnel_hp" && "$_funnel_hp" == "$_funnel_ts" ]]; then
  _funnel_ep="${REDIRECT_URI#*://}"
  _funnel_ep="${_funnel_ep%%/*}"
  if [[ "$_funnel_ep" == \[*\]* ]]; then
    _funnel_ep="${_funnel_ep#*]}"
    _funnel_ep="${_funnel_ep#:}"
  elif [[ "$_funnel_ep" == *:* ]]; then
    _funnel_ep="${_funnel_ep##*:}"
  else
    _funnel_ep=""
  fi
  if [[ -n "$_funnel_ep" && "$_funnel_ep" != "443" ]]; then
    warn "REDIRECT_URI names the funnel host with explicit port :$_funnel_ep — the funnel serves 443 only:"
    warn "  value: $REDIRECT_URI"
    warn "Register the bare :443-stripped spelling instead."
    if ! confirm "Keep it anyway?"; then exit 1; fi
  fi
  unset _funnel_ep
fi
unset _funnel_hp _funnel_ts

# Host/scheme gate the final value: the server fails closed on http
# non-loopback, non-loopback IPs, and non-FQDN hosts — a value passing the
# shape checks above can still be unregistrable (LAN IP, single label,
# underscore, *.localhost). https passes for tailnet FQDNs, any dotted
# FQDN with a lettered multi-char TLD (custom domains, nip.io), and
# loopback; http passes for loopback only. A dangling colon (host: with
# no port digits) fails outright like the server instead of offering a
# keep: no registration can hold it.
_final_hp="${REDIRECT_URI#*://}"
_final_hp="${_final_hp%%/*}"
_final_dangling=0
if [[ "$_final_hp" == \[*\]* ]]; then
  [[ "$_final_hp" == *"]:" ]] && _final_dangling=1
elif [[ "$_final_hp" == *:* ]]; then
  [[ -z "${_final_hp##*:}" ]] && _final_dangling=1
fi
if (( _final_dangling )); then
  warn "REDIRECT_URI has a dangling colon with no port — the server fails it closed:"
  warn "  value: $REDIRECT_URI"
  exit 1
fi
unset _final_hp _final_dangling
_final_hostport="${REDIRECT_URI#*://}"
_final_hostport="${_final_hostport%%/*}"
_final_scheme="${REDIRECT_URI%%://*}"
_final_host="$_final_hostport"
if [[ "$_final_host" == \[* ]]; then
  _final_host="${_final_host#[}"
  _final_host="${_final_host%%\]*}"
else
  _final_host="${_final_host%%:*}"
fi
_final_ok=0
if [[ "$_final_scheme" == "https" ]]; then
  # Tailnet names first (the common case), then any dotted FQDN with a
  # lettered multi-char TLD — custom domains and nip.io register exactly
  # like tailnet names (server validRedirectHost).
  if _valid_tsdns "$_final_host" 2>/dev/null || _valid_fqdn "$_final_host" 2>/dev/null; then
    _final_ok=1
  fi
elif [[ "$_final_scheme" == "http" ]]; then
  case "$_final_host" in localhost|127.0.0.1|::1) _final_ok=1;; esac
fi
# https loopback can never serve: direct host ports are plain HTTP and the
# funnel only publishes tailnet names — use plain `http` for direct
# loopback instead. Refused outright (no keep path): keeping it would
# register a URL nothing can deliver to.
if [[ "$_final_scheme" == "https" ]]; then
  case "$_final_host" in
    localhost|127.0.0.1|::1)
      warn "REDIRECT_URI is https loopback — nothing serves TLS on a direct host port:"
      warn "  value: $REDIRECT_URI"
      warn "Re-run with plain http for direct loopback (or a tailnet/FQDN name for funnel)."
      exit 1
      ;;
  esac
fi
if (( ! _final_ok )); then
  warn "REDIRECT_URI host/scheme is not registrable (https needs a dotted FQDN, http needs loopback):"
  warn "  value: $REDIRECT_URI"
  warn "The server fails these closed — Google would never call back."
  if ! confirm "Keep it anyway?"; then exit 1; fi
fi
# Loopback-port cross-check: a loopback REDIRECT_URI is served either
# direct by health-api on the mapped host port (HEALTH_HOST_PORT, compose
# default 8001) or through the proxy on APP_PORT (compose default 8080) —
# two distinct registrations, so either mapped port passes but anything
# else probes dead air and registers a URL nothing answers. http loopback
# only here — https loopback exits outright above.
if [[ "$_final_scheme" == "http" ]]; then
  case "$_final_host" in
    localhost|127.0.0.1|::1)
      _loop_port="${REDIRECT_URI#*://}"
      _loop_port="${_loop_port%%/*}"
      if [[ "$_loop_port" == \[*\]* ]]; then
        _loop_port="${_loop_port#*]}"
        _loop_port="${_loop_port#:}"
      elif [[ "$_loop_port" == *:* ]]; then
        _loop_port="${_loop_port##*:}"
      elif [[ "$_final_scheme" == "https" ]]; then
        _loop_port="443"
      else
        _loop_port="80"
      fi
      # Empty (dangling colon) was already rejected above; default ports
      # with nothing serving them (http:80, https:443 on loopback) fail
      # the same way.
      if [[ "$_loop_port" != "$_health_port" && "$_loop_port" != "$_proxy_port" ]]; then
        warn "loopback REDIRECT_URI port ($_loop_port) matches neither the health-api host port ($_health_port from $_health_port_src) nor the proxy port ($_proxy_port):"
        warn "  value: $REDIRECT_URI"
        warn "Direct loopback is served on the mapped health port, proxy loopback on the proxy port — fix the port or the vars. Either spelling registers, but only the one the browser reaches."
        if ! confirm "Keep it anyway?"; then exit 1; fi
      else
        note "loopback REDIRECT_URI port ($_loop_port): served — direct-health vs proxy are distinct registrations, this one matches."
      fi
      unset _loop_port
      ;;
  esac
fi
unset _final_hostport _final_scheme _final_host _final_ok
# ── Stage 4: funnel + public verification ─────────────────────────────────
# Position is load-bearing: this stage runs AFTER the final-URI gates, so
# REDIRECT_URI is final (preset/recorded/derived/kept resolved). A stage-4
# position before them would funnel for a URI later replaced.
stage "Publish the callback over HTTPS"
# Early exit before any funnel words: loopback http needs no public publish.
_funnel_final_host="${REDIRECT_URI#*://}"
_funnel_final_host="${_funnel_final_host%%/*}"
if [[ "$_funnel_final_host" == \[*\]* ]]; then
  _funnel_final_host="${_funnel_final_host#[}"
  _funnel_final_host="${_funnel_final_host%%\]*}"
else
  _funnel_final_host="${_funnel_final_host%%:*}"
fi
_funnel_final_host="$(printf '%s' "$_funnel_final_host" | tr '[:upper:]' '[:lower:]')"
_funnel_final_scheme="$(printf '%s' "${REDIRECT_URI%%://*}" | tr '[:upper:]' '[:lower:]')"
_funnel_skip=0
if [[ "$_funnel_final_scheme" == "http" ]]; then
  case "$_funnel_final_host" in
    localhost|127.0.0.1|::1)
      note "loopback REDIRECT_URI ($REDIRECT_URI): reached directly — skipping the public funnel."
      _funnel_skip=1
      ;;
  esac
fi
unset _funnel_final_host _funnel_final_scheme
if (( ! _funnel_skip )); then
say "Funnel will terminate TLS with a publicly-trusted certificate and forward"
say "to the existing proxy on $_proxy_target. Only ports 443/8443/10000 are"
say "allowed, so 443 it is."
printf '\n'
note "First run may prompt you to enable HTTPS certificates / MagicDNS for the"
note "tailnet, plus the 'funnel' node attribute in the tailnet policy file."
note "If it complains, enable them and re-run this stage:"
note "  DNS:     https://console.tailscale.com/admin/dns"
note "  Funnel attribute (Access controls → Add Funnel to policy):"
note "  https://console.tailscale.com/admin/acls"
printf '\n'

FOUT=$(mktemp) || { warn "temp file creation failed (TMPDIR full?) — re-run when /tmp is writable"; exit 1; }
# Re-runs are safe: if 443 already forwards to this proxy, keep it instead
# of erroring out of the wizard.
_funnel_status=$(tailscale funnel status 2>/dev/null || true)
# Real `funnel status` prints the public URL and the target on separate
# lines (https://<host>… on one, "|-- / proxy http://127.0.0.1:<port>" on
# another — port 443 is implied by https://, never printed next to the
# proxy port), so match across the whole output — but bind the port to the
# proxy word on its own line, or hint text mentioning a URL and the port
# elsewhere would take the fast path without the binding existing. Also require the
# served hostname itself: a preset/dry-run (or a tailnet rename) otherwise
# keeps host A while the URI, comment, and probe all use host B.
# Hostname first: most selective on the common mismatch path, so the two
# broader greps are skipped unless it hits. Boundary-anchored, not
# substring: a bare `grep -qF "$TS_DNS"` would also match
# `https://<TS_DNS>.evil.com` and take the fast path for a funnel that
# never serves this host (same class `_check_kept_host` guards with its
# trailing `([^a-z0-9.-]|$)`). Dots escaped — in ERE an unescaped dot
# matches any char, which would re-open the same hole one char wider.
# The -n guard is load-bearing:
# grep -qF "" matches every line, so without it an empty TS_DNS would
# turn the fast path into always-keep (empty exits earlier today, but the
# safety belongs on this line, not on ordering). The port comes from
# APP_PORT (validated numeric at the top), so a custom-port funnel that
# already serves matches instead of starting a duplicate.
if [[ -n "$TS_DNS" ]] && printf '%s\n' "$_funnel_status" | grep -qiE "https://${TS_DNS//./\\.}([^a-zA-Z0-9.-]|\$)" && printf '%s\n' "$_funnel_status" | grep -qiE "proxy.*${_proxy_port}|${_proxy_port}.*proxy" && printf '%s\n' "$_funnel_status" | grep -qiE 'https://|443'; then
  note "funnel already serving 443 → this proxy; keeping it"
  printf '%s\n' "$_funnel_status" | sed 's/^/      /' 2>/dev/null || true
  rm -f "$FOUT" || true; FOUT=""
fi
unset _funnel_status
if [[ -n "$FOUT" ]]; then
  if ! tailscale funnel --bg --https=443 "$_proxy_target" </dev/null >"$FOUT" 2>&1; then
    if grep -qiE -- "already|in use|exists" "$FOUT"; then
      note "funnel reports it is already serving; keeping the existing one"
      _check_kept_host
    else
      warn "funnel did not start:"
      sed 's/^/      /' "$FOUT" 2>/dev/null || true
      pause "Fix the above (usually MagicDNS/HTTPS in the admin console), then press Enter to retry."
      tailscale funnel --bg --https=443 "$_proxy_target" </dev/null >"$FOUT" 2>&1 || {
        if grep -qiE -- "already|in use|exists" "$FOUT"; then
          note "funnel reports it is already serving; keeping the existing one"
          _check_kept_host
        else
          warn "still failing:"; sed 's/^/      /' "$FOUT" 2>/dev/null || true; exit 1
        fi
      }
    fi
  fi
  sed 's/^/      /' "$FOUT" 2>/dev/null || true
  rm -f "$FOUT" || true; FOUT=""
fi
fi
unset _funnel_skip
printf '\n'
# Probe-target parts follow the registered URI — scheme and explicit port
# included — so fallback logic below answers for the right host:port.
# The URL itself is probed verbatim a few lines down.
_probe_scheme="${REDIRECT_URI%%://*}"
_probe_rest="${REDIRECT_URI#*://}"
_probe_hostport="${_probe_rest%%/*}"
case "$_probe_scheme" in http|https) ;; *) _probe_scheme="https";; esac
if [[ -z "$_probe_hostport" ]]; then
  _probe_hostport="$TS_DNS"
fi
unset _recorded_uri
# Compare the *final* URI (after any keep) against the funnel host. Any
# registered host other than TS_DNS — custom domain, loopback, or typo —
# is a funnel-vs-registration split: the funnel above serves TS_DNS only,
# so a custom host needs its own serving (reverse proxy/DNS), and a
# loopback host is reached directly, never through the funnel.
_uri_check="${REDIRECT_URI#*://}"
_uri_check="${_uri_check%%/*}"
if [[ "$_uri_check" == \[*\]* ]]; then
  _uri_check="${_uri_check#[}"
  _uri_check="${_uri_check%%\]*}"
else
  _uri_check="${_uri_check%%:*}"
fi
_uri_check="$(printf '%s' "$_uri_check" | tr '[:upper:]' '[:lower:]')"
if [[ -n "$_uri_check" && "$_uri_check" != "$TS_DNS" ]]; then
  case "$_uri_check" in
    localhost|127.0.0.1|::1)
      note "REDIRECT_URI is loopback ($_uri_check): reached directly, the funnel above does not apply."
      ;;
    *)
      warn "REDIRECT_URI host ($_uri_check) differs from TS_DNS ($TS_DNS):"
      warn "the funnel above serves TS_DNS only — serve the custom host separately,"
      warn "or Google registers a URL this funnel never delivers to."
      ;;
  esac
fi
unset _uri_check
say "Waiting for public DNS + certificate (up to ~10 minutes worst case)…"
# Preset/dry-run hostnames (or SKIP_PROBE=1) skip the 30× poll: a fake name
# would burn ~5 min of timeouts before the .env write. One opportunistic
# probe still reports status without the wait.
ok=0
issuer=""
# Probe the registered URI itself — path, case, query and all — not a
# reconstructed scheme+host: a knowingly-kept non-canonical value must
# prove (or fail) on its own bytes, or the probe greens a clean path while
# the registered string 404s/501s. The callback needs no bearer; without
# params a clean URL answers 400 (missing code/state) — that alone proves
# routing + handler (the 400 precedes the config check by design, so a
# param-less hit never 501s). Anything else (404/502/000) is a real
# failure to fix before registering.
# _probe_hostport was derived from the final canonical REDIRECT_URI above;
# TS_DNS is the fallback only if that derivation yielded nothing probabe
# (loopback http included — the probe speaks the URI's own scheme).
_probe_host="$_probe_hostport"
_probe_host="${_probe_host:-$TS_DNS}"
_probe_url="$REDIRECT_URI"
# 400/429 are the in-contract answers for a param-less callback hit
# (missing params / throttled) — both prove the route serves. curl without -f: -f would fail all of them and prove nothing.
# -L follows the mux clean-path redirect: a knowingly-kept double-slash URL
# 301s to the collapsed form before any handler runs, and the follow-up
# code is what proves the route (capped at 2 hops — this must terminate).
_probe_ok_code() {
  local code
  code=$(curl -sL --max-redirs 2 -o /dev/null -w '%{http_code}' --max-time 10 "$_probe_url" 2>/dev/null || echo "000")
  [[ "$code" == "400" || "$code" == "429" ]]
}
if (( _DNS_FROM_PRESET )) || [[ "${SKIP_PROBE:-0}" == "1" ]]; then
  if (( _DNS_FROM_PRESET )); then
    note "preset hostname — skipping the public-reachability wait"
  else
    note "SKIP_PROBE=1 — skipping the public-reachability wait on a discovered hostname"
  fi
  if _probe_ok_code; then
    ok=1
  elif (( _DNS_FROM_PRESET )); then
    note "not reachable from here right now (expected for a dry-run name)"
  else
    note "not reachable from here right now (stack stopped or still starting?)"
  fi
else
  for ((__i = 1; __i <= 30; __i++)); do
    if _probe_ok_code; then ok=1; break; fi
    printf '%s' '.'; sleep 10
  done
fi
printf '\n'
if (( ok )); then
  printf '  %s✓%s callback route answers: %s (400/429 both prove the route serves)\n' "$GREEN" "$RESET" "$_probe_url"
  # curl just proved TCP; bound the TLS handshake too so a TLS stall can't
  # outlast the probe budget — https only (loopback http has no TLS), at
  # the probed port. timeout is coreutils-Linux-only (macOS ships
  # gtimeout at best), so use it when present and run bare otherwise —
  # same portability line as the tmp-file prune below.
  _tls_host="$_probe_host"; _tls_port="443"; _tls_name="$_probe_host"
  if [[ "$_tls_host" == \[*\]* ]]; then
    # Split on `]` first like the other bracket branches: stripping `[`
    # then one trailing `]` turns `[::1]:8001` into `::1]:8001` (then
    # re-bracketed to the un-diallable `[::1]:8001]`).
    _tls_name="${_tls_host#[}"
    _tls_name="${_tls_name%%\]*}"
    _tls_rest="${_tls_host#*]}"; _tls_rest="${_tls_rest#:}"
    [[ -n "$_tls_rest" ]] && _tls_port="$_tls_rest"
    # Keep brackets on the connect target (bare ::1:port is ambiguous),
    # bare name on SNI — mirroring the IPv4 branch below.
    _tls_host="[$_tls_name]"
  elif [[ "$_tls_host" == *:* ]]; then
    _tls_port="${_tls_host##*:}"
    _tls_name="${_tls_host%%:*}"
    _tls_host="$_tls_name"
  fi
  if [[ "$_probe_scheme" == "https" ]] && command -v timeout >/dev/null 2>&1; then
    issuer=$(timeout 10 openssl s_client -connect "$_tls_host:$_tls_port" -servername "$_tls_name" </dev/null 2>/dev/null \
             | openssl x509 -noout -issuer 2>/dev/null || true)
  elif [[ "$_probe_scheme" == "https" ]]; then
    issuer=$(openssl s_client -connect "$_tls_host:$_tls_port" -servername "$_tls_name" </dev/null 2>/dev/null \
             | openssl x509 -noout -issuer 2>/dev/null || true)
  fi
  if [[ -n "$issuer" ]]; then
    note "$issuer"
    note "Google accepts Let's Encrypt-issued certs."
  fi
elif (( _DNS_FROM_PRESET )) || [[ "${SKIP_PROBE:-0}" == "1" ]]; then
  # Preset names were already reassured above — a fake name never
  # propagates, so the DNS-wait message below would misdirect those users.
  # An explicit skip on a discovered name gets no such reassurance.
  if (( _DNS_FROM_PRESET )); then
    note "continuing to the .env write without public reachability"
  else
    note "continuing to the .env write without public reachability (probe skipped by SKIP_PROBE=1 — verify serving separately)"
  fi
else
  warn "not reachable yet (DNS can take up to 10 min to propagate)."
  warn "You can continue — the URI below is still correct; re-run the probe later if needed."
fi
unset ok issuer _probe_host _probe_url _probe_scheme _probe_hostport _tls_host _tls_port _tls_name _tls_rest _canon_uri
printf '\n'
say "This is the exact string to register in Google (copy it verbatim):"
printf '\n  %s%s%s\n\n' "$BOLD" "$REDIRECT_URI" "$RESET"
note "Through the proxy, /api/ goes straight to health-api, which serves"
note "/api/connectors/callback — the one route that needs no bearer."
pause "Press Enter once you've copied it."

# ── Stage 5: GCP project + APIs ───────────────────────────────────────────
stage "Google Cloud: project + APIs"
# Everything from here on is browser-driven. confirm can't tell EOF from
# "no" (read || true, then a regex test) — and here "no" is the long
# create-project branch, so EOF-on-a-TTY would walk it instead of exiting
# like every other gate. ask fails loudly on EOF instead: same y/N line
# discipline on a terminal, friendly stop anywhere else.
note "This question is re-asked each run — it is navigation, not saved"
note "configuration (only the .env values persist)."
ask _HAVE_PROJ "Have a Google Cloud project with the Gmail and Calendar APIs enabled? [y/N]:" || { warn "no input — the wizard needs a terminal; re-run to try again"; exit 1; }
# Edge-trim like TS_HOST: a pasted "y " must not walk the create-project
# branch. Interior spaces still fail the regex and fall through correctly.
_HAVE_PROJ="${_HAVE_PROJ#"${_HAVE_PROJ%%[![:space:]]*}"}"
_HAVE_PROJ="${_HAVE_PROJ%"${_HAVE_PROJ##*[![:space:]]}"}"
_have_yes=0
# Strict yes (not confirm's ^[Yy] class): a typo'd "yn" must fall into the
# guided create-project branch, not skip it.
if [[ "$_HAVE_PROJ" =~ ^[Yy]([Ee][Ss])?$ ]]; then _have_yes=1; fi
unset _HAVE_PROJ
if (( _have_yes == 0 )); then
  step "Create a project (any name, e.g. agento-connectors)."
  open_url "https://console.cloud.google.com/projectcreate"
  pause "Press Enter once the project exists and is selected in the top bar."
  step "Enable the Gmail API."
  open_url "https://console.cloud.google.com/apis/library/gmail.googleapis.com"
  pause "Press Enter once it says 'API enabled'."
  step "Enable the Google Calendar API."
  open_url "https://console.cloud.google.com/apis/library/calendar-json.googleapis.com"
  pause "Press Enter once it says 'API enabled'."
else
  note "skipped (already enabled)"
fi
unset _have_yes

# ── Stage 6: consent screen ───────────────────────────────────────────────
stage "Google Cloud: consent screen + scopes"
say "User type EXTERNAL, publishing status TESTING, yourself as a test user."
note "Testing is the only free option here: publishing needs Google"
note "verification (a paid CASA assessment) for these restricted scopes."
note "Cost of Testing: refresh tokens expire after 7 days, so Gmail/Calendar"
note "will ask you to reconnect about weekly. Expected, not a bug."
printf '\n'
open_url "https://console.cloud.google.com/auth/overview"
note "If that 404s, use APIs & Services → OAuth consent screen."
printf '\n'
step "Branding: app name, your support email, developer contact. Save."
step "Audience: External. (If it defaults to Internal, you need Workspace — pick External.)"
step "Data access → Add or remove scopes. Add exactly these three:"
printf '\n'
printf '      %s\n' "https://www.googleapis.com/auth/gmail.readonly"
printf '      %s\n' "https://www.googleapis.com/auth/gmail.compose"
printf '      %s\n' "https://www.googleapis.com/auth/calendar.readonly"
printf '\n'
note "Leave 'Google APIs' filter on 'Manually add' if the picker won't find them."
step "Audience → Test users → Add users → your own Gmail address."
printf '\n'
if ! confirm "Consent screen configured with those three scopes and yourself as a test user?"; then
  warn "re-run the wizard when it is; nothing below needs redoing"
  exit 1
fi

# ── Stage 7: OAuth client ─────────────────────────────────────────────────
stage "Google Cloud: OAuth client"
say "Create a Web application client whose redirect URI is exactly:"
printf '\n  %s%s%s\n\n' "$BOLD" "$REDIRECT_URI" "$RESET"
open_url "https://console.cloud.google.com/auth/clients"
note "Or: APIs & Services → Credentials → Create credentials → OAuth client ID."
printf '\n'
step "Application type: Web application."
step "Authorized redirect URIs → Add URI → paste the string above, then Create."
note "One URI only. A typo here surfaces later as redirect_uri_mismatch in the"
note "browser while every server-side check still passes."
printf '\n'
pause "Press Enter once the client is created and the dialog shows ID + secret."
# Retry loop like TS_HOST above: a wrong paste must not burn the console
# work that led here. EOF still exits (a wizard needs a terminal).
while true; do
  step "Copy the Client ID (…apps.googleusercontent.com)."
  ask GOOGLE_CLIENT_ID "Client ID:" || { warn "no input — the wizard needs a terminal; re-run to try again"; exit 1; }
  step "Copy the Client secret (starts GOCSPX-). It is shown once."
  ask_secret GOOGLE_CLIENT_SECRET "Client secret (hidden):" || { warn "no input — the wizard needs a terminal; re-run to try again"; exit 1; }
  # Console copy-paste trails whitespace; trim the *edges* before the shape
  # checks (interior whitespace is a typo and must still fail, same rule as
  # TS_HOST — a full strip would silently promote a bad paste to good).
  GOOGLE_CLIENT_ID="${GOOGLE_CLIENT_ID#"${GOOGLE_CLIENT_ID%%[![:space:]]*}"}"
  GOOGLE_CLIENT_ID="${GOOGLE_CLIENT_ID%"${GOOGLE_CLIENT_ID##*[![:space:]]}"}"
  GOOGLE_CLIENT_SECRET="${GOOGLE_CLIENT_SECRET#"${GOOGLE_CLIENT_SECRET%%[![:space:]]*}"}"
  GOOGLE_CLIENT_SECRET="${GOOGLE_CLIENT_SECRET%"${GOOGLE_CLIENT_SECRET##*[![:space:]]}"}"
  _bad=""
  # Interior whitespace is a typo (tokens never contain any); the suffix/
  # prefix shape checks alone would let "abc .apps…" through.
  [[ "$GOOGLE_CLIENT_ID" == *[[:space:]]* ]] && _bad="client id (contains whitespace)"
  [[ "$GOOGLE_CLIENT_SECRET" == *[[:space:]]* ]] && _bad="${_bad:+$_bad and }client secret (contains whitespace)"
  [[ "$GOOGLE_CLIENT_ID" != *".apps.googleusercontent.com" ]] && _bad="${_bad:+$_bad and }client id (want …apps.googleusercontent.com)"
  [[ "$GOOGLE_CLIENT_SECRET" != GOCSPX-* ]] && _bad="${_bad:+$_bad and }client secret (want GOCSPX-…)"
  if [[ -z "$_bad" ]]; then unset _bad; break; fi
  warn "doesn't look like what Google issues: $_bad — check the paste"
  unset _bad
  # Escape hatch: today's shapes are GOCSPX- / …apps.googleusercontent.com,
  # but a Google-side rotation must not brick the wizard and burn the
  # console work above. Same confirm discipline as the TS_HOST loop —
  # except empties: keeping two blank pastes is never a rotation, so
  # that loops back to re-entry instead of travelling to the render check.
  if [[ -n "$GOOGLE_CLIENT_ID$GOOGLE_CLIENT_SECRET" ]] && confirm "Keep these values anyway?"; then break; fi
  if ! confirm "Re-enter both values?"; then
    warn "stopping — re-run the wizard to try again (console work above is unaffected)"
    exit 1
  fi
done

# ── Stage 8: write .env + verify ──────────────────────────────────────────
stage "Write .env and verify"
if [[ ! -f "$ENV_FILE" ]]; then
  # Branch the hint: overrides resolve outside the repo root, so "at
  # $REPO_DIR" would send override users looking in the wrong place.
  if [[ "$ENV_FILE" == "$REPO_DIR/.env" ]]; then
    warn "no $ENV_FILE — fresh checkout? run ./scripts/hermes.sh init first (or cp .env.example .env)"
  else
    warn "no $ENV_FILE (ENV_FILE override) — create it first, then re-run"
  fi
  exit 1
fi
# The four write_env calls below fail silently under set -e on ENOSPC/I-O
# (library); fail fast here with the message instead. File-writability is
# checked, but the backup needs the *directory* — check both, with the
# precise cause in each message.
if [[ ! -w "$ENV_FILE" ]]; then
  warn "no write permission on $ENV_FILE — fix ownership/permissions, then re-run"
  exit 1
fi
_env_dir=$(dirname "$ENV_FILE" 2>/dev/null || true)
if [[ ! -w "$_env_dir" ]]; then
  warn "no write permission in $_env_dir (backups land there) — fix ownership/permissions, then re-run"
  exit 1
fi
unset _env_dir
BACKUP=$(mktemp "$ENV_FILE.bak.$(date +%Y%m%d%H%M%S 2>/dev/null || true).$$.XXXXXX") || { warn "backup creation failed (TMPDIR/dir unwritable?) — stopping before anything is written"; exit 1; }
# mktemp rather than a hand-built name: O_EXCL and unpredictable suffix, so
# a pre-planted symlink cannot redirect this full-secret copy (the old
# existence test still left a check-then-copy race). It creates 0600, and
# the name still matches the *.env.bak.* gitignore + prune glob.
cp -- "$ENV_FILE" "$BACKUP" || { warn "backup failed (disk full? read-only dir?) — stopping before anything is written"; exit 1; }
# No touch: mktemp stamped mtime, and cp (without -p, dropped in round 37)
# rewrites it — the -ot prune already orders correctly.
# %q so the restore hint stays copy-pasteable for shell-special paths, not
# just spaces; reused verbatim by every later failure message.
printf -v _restore_cmd 'cp -p -- %q %q' "$BACKUP" "$ENV_FILE"
note "backup: $BACKUP (if the run is interrupted mid-write, restore with: $_restore_cmd)"
# Secrets are about to land in this file: 0600 regardless of what the
# checkout/editor left behind (a fresh file already gets 0600 in write_env) —
# and the backup holds the same secrets, so it gets 0600 too.
chmod 600 "$ENV_FILE" "$BACKUP" || { warn "chmod 600 failed — stopping before secrets are written"; exit 1; }
# Backups are full-secret copies — keep the 5 newest by mtime, prune the
# rest. Pure bash (-ot comparison): no ls parsing, no GNU-only flags.
# (`--` is kept on cp/rm/grep, which BSD documents; touch/chmod take none
# above, and both operands are absolute by now, so nothing to parse.)
# nullglob is restored afterwards — the wizard must not mutate shell
# options it didn't own (matters if this file is ever sourced).
_baks=(); _nullglob_off=0; shopt -q nullglob || _nullglob_off=1
shopt -s nullglob; _baks=("$ENV_FILE".bak.*)
# A switched ENV_FILE orphans the other name's backups (full-secret copies,
# gitignored but never pruned) — sweep the default name too when it differs.
# Different *names* cannot share a glob match, but different *spellings* of
# one path can, hence the -ef dedup immediately below.
if [[ "$ENV_FILE" != "$REPO_DIR/.env" ]]; then _baks+=("$REPO_DIR"/.env.bak.*); fi
# Different spellings of the same path (/tmp/d/.env vs /tmp/d/../d/.env)
# expand to one inode twice — dedup by -ef before counting, or the sweep
# prunes an extra unique backup and leaves a dangling entry behind.
if (( ${#_baks[@]} > 1 )); then
  _dedup=()
  for _b in "${_baks[@]}"; do
    _dup=0
    for _k in "${_dedup[@]}"; do [[ "$_b" -ef "$_k" ]] && { _dup=1; break; }; done
    (( _dup )) || _dedup+=("$_b")
  done
  _baks=("${_dedup[@]}")
  unset _dedup _dup _k
fi
if (( _nullglob_off )); then shopt -u nullglob; fi
_pruned=0
while (( ${#_baks[@]} > 5 )); do
  _oldest="${_baks[0]}"
  for _b in "${_baks[@]}"; do
    if [[ "$_b" -ot "$_oldest" ]]; then _oldest="$_b"; fi
  done
  rm -f -- "$_oldest" || { warn "backup prune failed for $_oldest (read-only dir?) — stopping before .env is modified; remove it by hand"; exit 1; }
  _kept=()
  for _b in "${_baks[@]}"; do
    [[ "$_b" != "$_oldest" ]] || continue
    _kept+=("$_b")
  done
  _baks=("${_kept[@]}"); _pruned=1
done
if (( _pruned )); then note "pruned .env backups to the last 5"; fi
unset _baks _b _oldest _kept _pruned _nullglob_off _dedup _dup _k

if v=$(_existing CONNECTORS_ENCRYPTION_KEY 2>/dev/null) && [[ -n "$v" ]]; then
  note "keeping the existing envelope key (rotating it would invalidate every stored grant)"
  CONNECTORS_ENCRYPTION_KEY="$v"
else
  CONNECTORS_ENCRYPTION_KEY=$(openssl rand -hex 32) || { warn "key generation failed (openssl/entropy?) — stopping before anything is written"; exit 1; }
  note "generated a new envelope key (AES-256-GCM, 32 bytes hex)"
fi
unset v

# A comment block once, refreshed on re-runs (the tailnet name can change);
# write_env only replaces key lines, so this survives re-runs either way.
# The recorded host always follows the redirect URL: on a custom-domain,
# preset, or recorded-keep path that host can differ from the
# daemon-derived TS_DNS, and the comment must name the registered host —
# not the funnel host that does not serve it.
_comment_host="${REDIRECT_URI#*://}"
_comment_host="${_comment_host%%/*}"
if [[ "$_comment_host" == \[*\]* ]]; then
  # Bracket/port aware (unlike _uri_host, which is tailnet-only): a custom
  # host must survive here, not fall back to TS_DNS silently.
  _comment_host="${_comment_host#[}"
  _comment_host="${_comment_host%%\]*}"
else
  _comment_host="${_comment_host%%:*}"
fi
_comment_host="${_comment_host:-$TS_DNS}"
# ASCII sentinel in one variable: non-ASCII dashes would silently fork the
# block if an editor normalized them, and two spellings would drift.
_marker='# -- Google connectors'
# Distinguish "marker absent" (grep rc=1 → append the block) from "read
# failed" (rc≥2 → stop): a bare `if ! grep` folds both into the append
# branch, which would append a duplicate block on an I/O error and only
# surface it on the next re-run's refresh path.
_marker_present=0
if grep -qF -- "$_marker" "$ENV_FILE"; then
  _marker_present=1
else
  _grep_rc=$?
  if (( _grep_rc != 1 )); then
    warn "could not read $ENV_FILE (grep exit $_grep_rc) — stopping before .env is modified"
    exit 1
  fi
fi
# The serving line matches the setup: funnel host → funnel sentence,
# anything else → registered-host sentence (a stale funnel sentence on a
# custom host is exactly the misdirection being removed).
if [[ "$_comment_host" == "$TS_DNS" ]]; then
  _cb_line="# Callback is served over Tailscale Funnel: https://$_comment_host"
else
  _cb_line="# Callback host: $_comment_host (registered here — served separately, NOT by the funnel above)"
fi
if (( _marker_present == 0 )); then
  {
    printf '\n'
    printf '# -- Google connectors (#316) -- added by setup wizard --\n'
    printf '%s\n' "$_cb_line"
    printf '# all-four-or-nothing: any missing piece leaves OAuth unconfigured (connect → 501).\n'
  } >> "$ENV_FILE" || { warn "comment block append failed — restore with: $_restore_cmd"; exit 1; }
else
  # Refresh the recorded hostname; keys below are fresh but this line is not.
  # Same tmp-file + cat pattern as the library's write_env, so a symlinked
  # .env stays a symlink (plain sed -i would replace it with a regular file).
  _cb_tmp=$(mktemp) || { warn "temp file creation failed (TMPDIR full?) — restore with: $_restore_cmd"; exit 1; }
  # No `--` after the script: BSD/macOS sed treats it as an operand, while
  # ENV_FILE is absolute here (canonicalized in stage 1), so not needed.
  # Matches either serving sentence shape from prior runs.
  sed "s|^# Callback \(is served over Tailscale Funnel: https://.*\|host: .*\)|$_cb_line|" "$ENV_FILE" > "$_cb_tmp" || {
    warn "hostname comment refresh failed — restore with: $_restore_cmd"
    exit 1
  }
  cat "$_cb_tmp" > "$ENV_FILE" || { warn "comment refresh write failed — restore with: $_restore_cmd"; exit 1; }
  rm -f "$_cb_tmp" || true; _cb_tmp=""
fi
unset _comment_host _marker _marker_present _grep_rc _cb_line

write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID" || { warn "write failed (disk full?) — restore with: $_restore_cmd"; exit 1; }
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET" || { warn "write failed (disk full?) — restore with: $_restore_cmd"; exit 1; }
write_env GOOGLE_REDIRECT_URL "$REDIRECT_URI" || { warn "write failed (disk full?) — restore with: $_restore_cmd"; exit 1; }
write_env CONNECTORS_ENCRYPTION_KEY "$CONNECTORS_ENCRYPTION_KEY" || { warn "write failed (disk full?) — restore with: $_restore_cmd"; exit 1; }

printf '\n'
say "Rendering compose to prove all four interpolate (values not printed)…"
# Same sudo-fallback pattern as scripts/lib/common.sh's podman_compose():
# a host whose user podman socket is missing needs sudo for compose.
# A hung (not absent) socket would block bare `podman info` forever, so
# bound it with timeout when present — same optional-timeout line as the
# s_client issuer print (timeout stays out of the required preflight).
_compose=(podman-compose)
_have_podman=0
if command -v timeout >/dev/null 2>&1; then
  if timeout 15 podman info &>/dev/null; then _have_podman=1; fi
else
  if podman info &>/dev/null; then _have_podman=1; fi
fi
if (( _have_podman == 0 )); then _compose=(sudo podman-compose); fi
unset _have_podman
# mktemp (mode 600) rather than fixed /tmp names: the render contains all
# four secret values interpolated, and a kill -9 would leave fixed paths
# behind on world-readable /tmp. Registered in the EXIT trap above.
RENDER_OUT=$(mktemp) || { warn "temp file creation failed (TMPDIR full?) — stopping before the render"; exit 1; }
RENDER_ERR=$(mktemp) || { warn "temp file creation failed (TMPDIR full?) — stopping before the render"; exit 1; }
# Deliberately unbounded: `config` is client-side YAML rendering (the
# socket-touching detection above is already timeout-bounded), so a hang
# here means a wedged compose binary, not a slow network — no budget
# would make that failure friendlier than the exit below.
if ( cd -- "$REPO_DIR" && "${_compose[@]}" --env-file "$ENV_FILE" -f docker/docker-compose.yml config ) >"$RENDER_OUT" 2>"$RENDER_ERR"; then
  # Empty vars render as KEY: '' — the quote alone must not satisfy the
  # check, or a missing var reads as "reaches the pi service".
  # Scoped per service: the same four keys are mapped into both pi and
  # health-api, and a whole-config grep would pass while one mapping is
  # missing (the health-api mapping is what connect/callback actually
  # read — a green proof with it missing 501s at runtime).
  _service_block() {
    awk -v svc="$1" '
      $0 ~ "^  " svc ":$" { inblock=1; next }
      inblock && /^  [a-zA-Z0-9_-]+:$/ { exit }
      inblock { print }
    ' "$RENDER_OUT"
  }
  _render_missing=""
  # Health-api is REQUIRED (it serves connect/callback); pi is warn-only
  # (its verbs die with the #494 teardown, after which a required check
  # here would block setup on a correct tree).
  for _svc in health-api pi; do
    _block_out=$(mktemp) || { warn "temp file creation failed (TMPDIR full?) — stopping before the render"; exit 1; }
    _service_block "$_svc" >"$_block_out"
    for k in GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET GOOGLE_REDIRECT_URL CONNECTORS_ENCRYPTION_KEY; do
      if grep -qE -- "^[[:space:]]*(-[[:space:]]*)?${k}[:=][[:space:]]*[\"']?[[:space:]]*[^\"'[:space:]]" "$_block_out"; then
        printf '  %s✓%s %s present for %s in rendered compose config\n' "$GREEN" "$RESET" "$k" "$_svc"
      else
        # Same rc discipline as the comment-block grep: rc=1 is a genuine
        # empty render, rc≥2 is a read failure that must not masquerade as
        # "renders EMPTY" (the message would send the reader to the wrong fix).
        _render_rc=$?
        if (( _render_rc != 1 )); then
          warn "could not read the rendered config (grep exit $_render_rc) — the .env writes stand, but nothing is verified"
          rm -f "$_block_out" || true
          exit 1
        fi
        if [[ "$_svc" == "pi" ]]; then
          # Warn-only: the pi verbs (and their env mapping) die with the
          # #494 teardown — a required check here would block setup on a
          # correct tree the moment they land.
          printf '  %s!%s %s missing for %s (serving copy is health-api; pi mapping dies with #494)\n' "$YELLOW" "$RESET" "$k" "$_svc"
        else
          printf '  %s✗%s %s renders EMPTY for %s — fix it before restarting\n' "$YELLOW" "$RESET" "$k" "$_svc"
          _render_missing="${_render_missing:+$_render_missing }${_svc}/${k}"
        fi
      fi
    done
    rm -f "$_block_out" || true
  done
  if [[ -n "$_render_missing" ]]; then
    warn "empty render for: ${_render_missing} — an empty value is the misconfiguration this step exists to catch"
    exit 1
  fi
  unset _render_missing _render_rc _block_out _svc
else
  # The subshell's cd can only fail on a tree deleted mid-run (REPO_DIR is
  # fail-loud guarded above), but attributing that to compose would send the
  # reader debugging the wrong thing.
  if ! ( cd -- "$REPO_DIR" ) 2>/dev/null; then
    warn "cannot enter $REPO_DIR (deleted or unreadable mid-run) — the .env writes stand, but nothing is verified"
  else
    warn "compose render failed (the .env writes stand, but nothing is verified — fix compose and re-run):"
  fi
  sed 's/^/      /' "$RENDER_ERR" 2>/dev/null || true
  exit 1
fi
rm -f "$RENDER_OUT" "$RENDER_ERR" || true; RENDER_OUT=""; RENDER_ERR=""

# Stage outputs persist; these three were pure temps (the URL was opened long
# ago, the preset flags last read by the comment host).
unset URL _DNS_FROM_PRESET _URI_FROM_PRESET k _restore_cmd

finish

# finish clears the screen, wiping the render ✓ lines just earned; restate
# the proof beside the comparison step that now leans on it.
note "render proof (cleared with the stage above): all four keys interpolated non-empty for health-api (any pi lines above are warn-only, not proof)"

# ── Closing checklist (not a stage; nothing else is automated) ────────────
printf '%s  Next, in this order:%s\n' "$BOLD" "$RESET"
printf '  1. Restart now so every container picks up the new .env values\n'
printf '     (health-api reads all four OAuth vars too — a pi-only recreate\n'
printf '     leaves connect 501ing on stale config):\n'
printf '     ./scripts/hermes.sh restart recreates them (a plain container\n'
printf '     restart without recreation will not pick up .env changes).\n'
printf '  2. Compare the canonical string health-api logs at boot:\n'
printf -v _compose_file '%q' "$REPO_DIR/docker/docker-compose.yml"
printf '       %s -f %s logs health-api | grep -E "OAuth (configured|unavailable|redirect invalid)"\n' "${_compose[*]}" "$_compose_file"
unset _compose_file
printf '     (if the render step above used sudo, prefix sudo here too)\n'
printf '     The narrowed pattern skips the "boot check started" starter\n'
printf '     line on purpose: init runs detached, so poll until a status\n'
printf '     line lands (repeat the grep a few seconds apart) — an empty\n'
printf '     result means "not printed yet", not "misconfigured".\n'
printf '     Expect the configured line; an unavailable line names the\n'
printf '     reason (fix that first) — with what is registered in Google.\n'
printf '     They must match byte-for-byte;\n'
printf '     the log prints the canonical form, so register THAT.\n'
printf '  3. In the app: Settings → Connectors → Connect Gmail. Expect the\n'
printf '     "app isn'"'"'t verified" warning (Testing mode) → Advanced → proceed.\n'
printf '  4. Re-add gmail/calendar inside the "mcpServers" object in pi/mcp.json\n'
printf '     by hand (unwired until OAuth is configured; OAuth alone does not\n'
printf '     bring the agent tools back). The "reports" entry is currently last\n'
printf '     and has no trailing comma — add one after it, then paste (commas\n'
printf '     after reports and gmail, none after calendar):\n'
printf '       "gmail": {"command": "/usr/local/bin/gmail"},\n'
printf '       "calendar": {"command": "/usr/local/bin/calendar"}\n'
printf '     then ./scripts/hermes.sh restart again so the pi container picks\n'
printf '     them up (entrypoint refuses to start if a server fails to connect).\n'
printf '     Verify with: python3 -m json.tool pi/mcp.json (invalid JSON\n'
printf '     crash-loops the container — the lint is the step, not optional).\n'
printf '\n'
printf '  Re-running this wizard is safe: it keeps existing values as defaults.\n'
printf '  Envelope key: BACKUP FIRST — rotating it invalidates every stored grant.\n\n'
unset _compose
}

run_wizard "$@"; exit
